use clap_complete::engine::{ArgValueCompleter, CompletionCandidate};

fn md_file_completer(current: &std::ffi::OsStr) -> Vec<CompletionCandidate> {
    use std::path::Path;
    let current_str = current.to_string_lossy().to_string();
    // Handle special cases: "." and ".." without trailing slash are treated as empty (list current dir)
    // Based on observed behavior: "." and ".." list current dir without prefix
    let effective = if current_str == "." || current_str == ".." {
        String::new()
    } else {
        current_str.clone()
    };
    // Split into dir part and file prefix
    let (dir_part, file_prefix) = if let Some(pos) = effective.rfind('/') {
        let (d, f) = effective.split_at(pos + 1);
        (d.to_string(), f.to_string())
    } else {
        (String::new(), effective.clone())
    };
    // Determine search directory
    let search_dir: std::path::PathBuf = if dir_part.is_empty() {
        match std::env::current_dir() {
            Ok(d) => d,
            Err(_) => return vec![],
        }
    } else if dir_part.starts_with('/') {
        Path::new(&dir_part).to_path_buf()
    } else if dir_part.starts_with("~/") || dir_part == "~" {
        let home = match std::env::var("HOME") {
            Ok(h) => h,
            Err(_) => return vec![],
        };
        if dir_part == "~" || dir_part == "~/" {
            Path::new(&home).to_path_buf()
        } else {
            // "~/..."
            let rest = &dir_part[2..];
            Path::new(&home).join(rest)
        }
    } else {
        match std::env::current_dir() {
            Ok(cwd) => cwd.join(&dir_part),
            Err(_) => return vec![],
        }
    };
    let read = match std::fs::read_dir(&search_dir) {
        Ok(r) => r,
        Err(_) => return vec![],
    };
    let mut out = Vec::new();
    let prefix_lower = file_prefix.to_lowercase();
    for entry in read {
        let entry = match entry {
            Ok(e) => e,
            Err(_) => continue,
        };
        let file_name_os = entry.file_name();
        let file_name = file_name_os.to_string_lossy().to_string();
        // Case-insensitive prefix match
        if !file_name.to_lowercase().starts_with(&prefix_lower) {
            continue;
        }
        let path = entry.path();
        let is_dir = path.is_dir();
        if is_dir {
            // Always include dirs
            let suggestion = if dir_part.is_empty() {
                format!("{}/", file_name)
            } else if dir_part == "./" {
                // Special: "./" prefix is stripped for current dir
                format!("{}/", file_name)
            } else {
                format!("{}{}/", dir_part, file_name)
            };
            out.push(CompletionCandidate::new(suggestion).help(Some("directory".into())));
        } else {
            // Only .md/.markdown (case-insensitive)
            let is_md = if let Some(ext) = path.extension().and_then(|e| e.to_str()) {
                let lower = ext.to_lowercase();
                lower == "md" || lower == "markdown"
            } else {
                false
            };
            if !is_md {
                continue;
            }
            let suggestion = if dir_part.is_empty() {
                file_name.clone()
            } else if dir_part == "./" {
                file_name.clone()
            } else {
                format!("{}{}", dir_part, file_name)
            };
            out.push(CompletionCandidate::new(suggestion));
        }
    }
    // Do NOT sort, preserve readdir order to match original
    out
}"""
