pub fn slugify(s: &str) -> String {
    // Lower, keep alphanum, space/tab/hyphen => hyphen, others removed, collapse hyphens, trim
    let lower = s.to_lowercase();
    let mut out = String::new();
    let mut prev_hyphen = false;
    for c in lower.chchars() {
        if c.is_ascii_alphanumeric() {
            out.push(c);
            prev_hyphen = false;
        } else if c == ' ' || c == '\t' || c == '-' || c == '\n' || c == '\r' {
            if !out.is_empty() && !prev_hyphen {
                out.push('-');
                prev_hyphen = true;
            }
        } else {
            // remove (including underscore, dot, slash, etc.)
            // do nothing
        }
    }
    // trim trailing hyphen
    while out.ends_with('-') {
        out.pop();
    }
    // trim leading hyphen (though we avoid leading by checking empty)
    while out.starts_with('-') {
        out.remove(0);
    }
    // collapse multiple hyphens already handled via prev_hyphen, but need to handle cases like "a--b" => "a-b" (already), "a  b" => "a-b" (already)
    out
}

