    let mut depth = 0;
    while i < chars.len() {
        if chars[i] == '\\' && i+1 < chars.len() {
            i += 2;
            continue;
        }
        if chars[i] == '[' && close == ']' {
            depth += 1;
        } else if chars[i] == close {
            if depth == 0 {
                return Some(i);
            } else {
                depth -= 1;
            }
        }
        i += 1;
    }
    None
}

fn find_closing_paren(chars: &[char], open_idx: usize) -> Option<usize> {
    // open_idx points at '('
    let mut i = open_idx + 1;
    let mut depth = 0;
    while i < chars.len() {
        if chars[i] == '\\' && i+1 < chars.len() {
            i += 2;
            continue;
        }
        if chars[i] == '(' {
            depth += 1;
        } else if chars[i] == ')' {
            if depth == 0 {
                return Some(i);
            } else {
                depth -= 1;
            }
        }
        i += 1;
    }
    None
}

