// Check if line is fenced code delimiter: ^ {0,3}(```+|~~~+)
fn is_fence(line: &str) -> Option<(char, usize, String)> {
    let trimmed_start = line.trim_start_matches(' ');
    let leading = line.len() - trimmed_start.len();
    if leading > 3 { return None; }
    if trimmed_start.starts_with("```") || trimmed_start.starts_with("~~~") {
        let ch = trimmed_start.chars().next().unwrap();
        let len = trimmed_start.chars().take_while(|&c| c==ch).count();
        let rest = trimmed_start[len..].to_string();
        return Some((ch, len, rest));
    }
    None
}

// Check if line is thematic break: ^ {0,3}((\* *\* *\*+)|( - * - * -+)|(_ *_ *_*+))\s*$ ? Simplified: only *, -, _ with spaces, at least 3
fn is_hr(line: &str) -> bool {
    let t = line.trim();
    if t.is_empty() { return false; }
    // Remove spaces
    let nospace: String = t.chars().filter(|&c| c!=' ' && c!='\t').collect();
    if nospace.len() < 3 { return false; }
    if nospace.chars().all(|c| c=='*') || nospace.chars().all(|c| c=='-') || nospace.chars().all(|c| c=='_') {
        return true;
    }
    false
}

