fn is_list_item(line: &str)->bool{
    let ts=line.trim_start_matches(' ');
    let leading=line.len()-ts.len();
    if leading>3{return false;}
    if ts.starts_with("- ")||ts.starts_with("* ")||ts.starts_with("+ ")||ts.starts_with("-\t")||ts.starts_with("*\t")||ts.starts_with("+\t"){return true;}
    // Ordered?
    let chars:Vec<char>=ts.chars().collect();
    let mut idx=0;while idx<chars.len()&&chars[idx].is_ascii_digit(){idx+=1;}
    if idx>0&&idx<chars.len()&&(chars[idx]=='.'||chars[idx]==')'){
        if idx+1<chars.len()&&(chars[idx+1]==' '||chars[idx+1]=='\t'){return true;}
    }
    false
}

fn parse_globals(lines: &[String], refs: &HashMap<String,String>, fence_states: Vec<bool>)->(Vec<CodeBlock>,Vec<Link>,Vec<Table>,Vec<List>){
    let mut codes=Vec::new();
    let mut links=Vec::new();
    let mut tables=Vec::new();
    let mut lists=Vec::new();
    // Code: fenced + indented? For queries, indented code IS code. For simplicity, parse fenced here, and indented separately?
    // Fenced: iterate lines, track fences (reuse fence_states? But fence_states was for heading parsing, which tracks fences correctly. For code extraction, need to extract content and language.
    let mut i=0;
    let mut in_f=false;let mut fch=' ';let mut flen=0;let mut clang:Option<String>=None;let mut ccontent=Vec::new();
    while i<lines.len(){
        let line=&lines[i];
        if let Some((ch,len,rest))=is_fence(line){
            if !in_f{
                in_f=true;fch=ch;flen=len;
                let lang=rest.trim();
                clang=if lang.is_empty(){None}else{Some(lang.to_string())};
                ccontent.clear();
                i+=1;continue;
            }else{
                if ch==fch&&len>=flen&&rest.trim().is_empty(){
                    // Close
                    codes.push(CodeBlock{language:clang.clone(),content:ccontent.join("\n")});
                    in_f=false;clang=None;ccontent.clear();
                    i+=1;continue;
                }else{
                    ccontent.push(line.clone());i+=1;continue;
                }
            }
        }else{
            if in_f{ccontent.push(line.clone());}
            i+=1;
        }
    }
    // Unclosed fence? If in_f at end, push? Probably yes (content until EOF). Let's push.
    if in_f{
        codes.push(CodeBlock{language:clang.clone(),content:ccontent.join("\n")});
    }
