    // But need to avoid double-counting fenced? Fenced lines are already handled (inside fences). For indented, skip lines inside fences (fence_states true) and skip list items, headings, etc.? Simplify: iterate lines not in fence, if line starts with 4 spaces or tab and is not blank, collect as indented code block (strip 4 spaces or tab?).
    // For "    code" (4 spaces + "code"), content "code" (stripped). For "    code1\n    code2", content "code1\ncode2" (each stripped). Good (matches earlier: query code for "    code1\n    code2" gave "code1\ncode2").
    // What about indented code after list? e.g., "  - nested" (2 spaces, not 4) is not indented code. Good.
    // What about "    # hello" (4 spaces + "# hello")? That's indented code with "#"? For queries, it IS code (we saw stats code_blocks 1 for "    # hello"). Good, our logic will treat as code.
    let mut j=0;
    while j<lines.len(){
        if fence_states[j]{j+=1;continue;}
        let line=&lines[j];
        // Check blank? Skip.
        if line.trim().is_empty(){j+=1;continue;}
        // Check if line is list, heading, table, hr, blockquote, fence? If so, not indented code. For simplicity, check leading spaces >=4 and not list/heading? Actually list items can have 4+ leading spaces? e.g., "    - item" (4 spaces + "- ")? That's indented list? Unlikely. For simplicity, if line has 4+ leading spaces (or tab), and is not blank, treat as indented code, unless it's list item with 4+ spaces? Hmm.
        let leading_spaces=line.len()-line.trim_start_matches(' ').len();
        let starts_tab=line.starts_with('\t');
        if leading_spaces>=4||starts_tab{
            // Check if it's list item? After stripping 4 spaces, does it look like list? For "    - item" (4 spaces + "- "), stripping 4 gives "- item" which is list. Should it be list or code? In markdown, 4 spaces after para is code, but list markers? Complex. For simplicity, if after stripping 4 spaces, line is list item, treat as list, not code? But original for "    - item"? Unlikely tested. Skip.
            // Collect consecutive indented lines
            let mut block_lines=Vec::new();
            while j<lines.len()&&!fence_states[j]{
                let l=&lines[j];
                if l.trim().is_empty(){
                    // Blank inside indented code? Blank ends? Actually blank line ends indented code? For "    code1\n\n    code2", are they separate blocks or one? Likely separate (blank breaks). So break on blank.
                    break;
                }
                let ls=l.len()-l.trim_start_matches(' ').len();
                let st=l.starts_with('\t');
                if ls>=4||st{
                    // Strip 4 spaces or tab (one tab = 4? Actually tab counts as 4? For simplicity, strip 4 spaces or 1 tab)
                    let stripped=if st{
                        // Strip one leading tab
                        l[1..].to_string()
                    }else{
                        l[4..].to_string()
                    };
                    block_lines.push(stripped);
                    j+=1;
                }else{
                    break;
                }
            }
            if !block_lines.is_empty(){
                codes.push(CodeBlock{language:None,content:block_lines.join("\n")});
                continue;
            }
        }
        j+=1;
    }
    // Links: extract from entire text joined? Need to exclude code blocks (fenced and indented) and reference definitions? For queries, links inside code should NOT be counted. Our extract_links currently doesn't exclude code. Need to exclude code blocks.
    // To exclude code, build text without code: iterate lines, skip fenced code content and indented code blocks, also skip reference definition lines? Reference definitions like "[ref]: url" should not be counted as links themselves (they define, not use). Our extract_links already handles definitions (skips them as not links). Good.
    // For code exclusion, create filtered text: join lines excluding code blocks (fenced content + fences themselves? Fences themselves contain ```, not links. Indented code content? Should exclude.
    // Simplify: build a set of line indices that are code (fenced content + fences, indented). Then join non-code lines with "\n" and extract links.
    // To compute code line indices, re-track fences and indented as above.
    // For simplicity, reuse fence_states for fenced (true means inside fence, including fences? Our fence_states marks fence lines as true as well. Good. So skip lines where fence_states true? But fence_states true includes fence delimiters themselves (```), which don't contain links anyway. Good.
    // For indented, need to compute similarly. Let's compute indented indices as above.
    let mut is_code_line=vec![false;lines.len()];
    for idx in 0..lines.len(){if fence_states[idx]{is_code_line[idx]=true;}}
    // Indented: mark as above
    {
        let mut jj=0;
        while jj<lines.len(){
            if fence_states[jj]{jj+=1;continue;}
            let line=&lines[jj];
            if line.trim().is_empty(){jj+=1;continue;}
            let ls=line.len()-line.trim_start_matches(' ').len();
            let st=line.starts_with('\t');
            if ls>=4||st{
                let mut k=jj;
                while k<lines.len()&&!fence_states[k]{
                    let l=&lines[k];
                    if l.trim().is_empty(){break;}
                    let ls2=l.len()-l.trim_start_matches(' ').len();
                    let st2=l.starts_with('\t');
                    if ls2>=4||st2{is_code_line[k]=true;k+=1;}else{break;}
                }
                jj=k;continue;
            }
            jj+=1;
        }
    }
    let mut text_for_links=String::new();
    for (idx,line) in lines.iter().enumerate(){
        if is_code_line[idx]{text_for_links.push('\n');continue;}
        // Skip reference definition lines? They look like "[ref]: url". Our extract_links handles them (skips), but to be safe, skip lines that are definitions? Actually definitions could contain links? No. Keep them (extract will skip).
        // Skip table delim lines? They contain "---", not links. Keep.
        text_for_links.push_str(line);
        text_for_links.push('\n');
    }
    links=extract_links(&text_for_links,&refs);
    // Tables: parse from lines (excluding code)
    {
        let mut k=0;
        while k<lines.len(){
            if is_code_line[k]{k+=1;continue;}
            let line=&lines[k];
            if line.trim().is_empty(){k+=1;continue;}
            if line.contains('|')&&k+1<lines.len()&&!is_code_line[k+1]&&is_table_delim(&lines[k+1]){
                let headers=split_table_row(line);
                let delim_cells=split_table_row(&lines[k+1]);
                // Check header and delim have same column count? If not, maybe not table? Original for "| a |\n|---|\n" (1 col) works. For "a | b\n--- | ---\n" (2 cols) works. For mismatched? Assume table anyway.
                let aligns=parse_table_align(&delim_cells);
                let mut rows=Vec::new();
                let mut m=k+2;
                while m<lines.len(){
                    if is_code_line[m]{break;}
                    let l=&lines[m];
                    if l.trim().is_empty(){break;}
                    if !l.contains('|'){break;}
                    rows.push(split_table_row(l));
                    m+=1;
                }
                tables.push(Table{headers,alignments:aligns,rows});
                k=m;continue;
            }
            k+=1;
        }
    }
    // Lists: parse from lines (excluding code) similar to parse_blocks list logic, but global (multiple lists).
    // For queries, .list returns each list block separately (e.g., rich2.md has 2 lists: unordered and ordered, returned as 2 separate list objects in json array, but in plain they are concatenated? Earlier rich2 .list plain gave "- item1\n- item2\n  nested?\n1. ordered1\n2. ordered2\n" (both lists concatenated with \n). In json, array of 2. Good.
    // To parse globals, iterate lines, collect consecutive list blocks (separated by blank?).
    {
        let mut k=0;
        while k<lines.len(){
            if is_code_line[k]{k+=1;continue;}
            let line=&lines[k];
            if line.trim().is_empty(){k+=1;continue;}
            if is_list_item(line){
                // Collect list block lines (until blank or non-list non-indented)
                let mut list_lines:Vec<String>=Vec::new();
                let mut m=k;
                while m<lines.len(){
                    if is_code_line[m]{break;}
                    let l=&lines[m];
                    if l.trim().is_empty(){break;}
                    if is_list_item(l){list_lines.push(l.clone());m+=1;}
                    else if l.starts_with(' ')||l.starts_with('\t'){list_lines.push(l.clone());m+=1;}
                    else{break;}
                }
                // Parse list_lines into List (similar to parse_blocks logic, but simplified for global: need ordered, items with content/checked)
                // Determine ordered from first
                let first=list_lines[0].trim_start();
                let ordered=first.chars().next().map(|c|c.is_ascii_digit()).unwrap_or(false);
                // Parse items with nesting (merge nested as before)
                let mut items:Vec<ListItem>=Vec::new();
                let mut cur_content:Option<String>=None;
                let mut cur_checked:Option<bool>=None;
                let mut base_indent:Option<usize>=None;
                for lline in &list_lines{
                    if is_list_item(lline){
                        let indent=lline.len()-lline.trim_start_matches(' ').len();
                        let trimmed=lline.trim_start();
                        let content_part=if trimmed.starts_with("- ")||trimmed.starts_with("* ")||trimmed.starts_with("+ ")||trimmed.starts_with("-\t")||trimmed.starts_with("*\t")||trimmed.starts_with("+\t"){
                            trimmed[2..].to_string()
                        }else{
                            let chars:Vec<char>=trimmed.chars().collect();
                            let mut idx2=0;while idx2<chars.len()&&chars[idx2].is_ascii_digit(){idx2+=1;}
                            chars[idx2+2..].iter().collect()
                        };
                        let mut checked=None;let mut ccontent=content_part.clone();
                        if ccontent.starts_with("[ ] "){checked=Some(false);ccontent=ccontent[4..].to_string();}
                        else if ccontent.starts_with("[x] ")||ccontent.starts_with("[X] "){checked=Some(true);ccontent=ccontent[4..].to_string();}
                        if base_indent.is_none(){
                            base_indent=Some(indent);
                            cur_content=Some(ccontent);cur_checked=checked;
                        }else{
                            let base=base_indent.unwrap();
                            if indent==base{
                                if let Some(pc)=cur_content.take(){items.push(ListItem{content:pc,checked:cur_checked});}
                                cur_content=Some(ccontent);cur_checked=checked;
                            }else if indent>base{
                                if let Some(ref mut pc)=cur_content{
                                    pc.push('\n');
                                    for _ in 0..indent{pc.push(' ');}
                                    pc.push_str(&ccontent);
                                }
                            }else{
                                if let Some(pc)=cur_content.take(){items.push(ListItem{content:pc,checked:cur_checked});}
                                cur_content=Some(ccontent);cur_checked=checked;base_indent=Some(indent);
                            }
                        }
                    }else{
                        if let Some(ref mut pc)=cur_content{pc.push('\n');pc.push_str(lline.trim_end());}
                    }
                }
                if let Some(pc)=cur_content.take(){items.push(ListItem{content:pc,checked:cur_checked});}
                lists.push(List{ordered,items});
                k=m;continue;
            }
            k+=1;
        }
    }
    (codes,links,tables,lists)
}
