fn is_list_item(line: &str)->bool{
    let ts=line.trim_start_matches(' ');
    let leading=line.len()-ts.len();
    if leading>3{return false;}
    if ts.starts_with("- ")||ts.starts_with("* ")||ts.starts_with("+ ")||ts.starts_with("-\t")||ts.starts_with("*\t")||ts.starts_with("+\t"){return true;}
    // Ordered?
    let chars:Vec<char>=ts.chars().collect();
    let mut idx=0;while idx<chars.len()&&chars[idx].is_ascii_digit(){idx+=1;}
    if idx>0&&idx<chars.len()&&(chars[idx]=='.'||chars[idx]==')'){
        if idx+1<chars.len()&&(chars[idx+1]==' '||chars[idx+1]=='\t'){return true;}
    }
    false
}

