        let fmt = matches.get_one::<String>("query-output").map(|s| s.as_str());
        // Read input
        let content = match read_input(&matches) {
            Ok(c) => c,
            Err((msg, code)) => { eprint!("{}", msg); return code; }
        };
        let doc = crate::markdown::parse_document(&content);
        match crate::query::run_query(q, &doc, fmt) {
            Ok(out) => { print!("{}", out); 0 }
            Err(e) => { eprint!("{}", e); 1 }
        };
        // run_query returns Result<String,String> where Err is already formatted error with trailing \n\n? Need to ensure.
        // Actually run_query stub returns Ok. Implement later.
        return 0;
    }
    // For count/tree/section/list, need to handle output/filter/level etc.
    if matches.get_flag("count") {
        let content = match read_input(&matches) {
            Ok(c) => c,
            Err((msg, code)) => { eprint!("{}", msg); return code; }
        };
        let doc = crate::markdown::parse_document(&content);
        print_count(&doc);
        return 0;
    }
    if matches.get_flag("tree") {
        let content = match read_input(&matches) {
            Ok(c) => c,
            Err((msg, code)) => { eprint!("{}", msg); return code; }
        };
        let doc = crate::markdown::parse_document(&content);
        let output = matches.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("plain");
        if output == "json" {
            print_tree_json(&doc);
        } else {
            // plain or tree both give tree format, ignoring filters
            print_tree(&doc);
        }
        return 0;
    }
    if let Some(sec) = matches.get_one::<String>("section") {
        let content = match read_input(&matches) {
            Ok(c) => c,
            Err((msg, code)) => { eprint!("{}", msg); return code; }
        };
        let doc = crate::markdown::parse_document(&content);
        return print_section(&doc, sec);
    }
    if matches.get_flag("list") {
        let content = match read_input(&matches) {
            Ok(c) => c,
            Err((msg, code)) => { eprint!("{}", msg); return code; }
        };
        let doc = crate::markdown::parse_document(&content);
        let output = matches.get_one::<String>("output").map(|s| s.as_str()).unwrap_or("plain");
        if output == "tree" {
            eprint!("Use --tree for tree output\n");
            return 1;
        } else if output == "json" {
            print_list_json(&doc);
            return 0;
        } else {
            // plain with filters (bug: if both level and filter, ignore filter)
            let level = matches.get_one::<u64>("level").copied();
            let filter = matches.get_one::<String>("filter").map(|s| s.as_str());
            print_list(&doc, level, filter);
            return 0;
        }
    }
    // at-line subcommand?
    if let Some((sub, _submatches)) = matches.subcommand() {
        if sub == "at-line" {
            // Always empty output, exit 0 (clap already validated LINE)
            return 0;
        }
        // help handled by clap, shouldn't reach here
