    let color_mode = matches.get_one::<String>("color-mode").cloned();
    let no_images = matches.get_flag("no-images");
    let images = matches.get_flag("images");
    crate::tui::run_tui(files, theme, color_mode, no_images, images)
}

fn read_input(matches: &clap::ArgMatches) -> Result<String, (String, i32)> {
    let files: Vec<String> = matches.get_many::<String>("FILE").map(|v| v.cloned().collect()).unwrap_or_default();
    if files.is_empty() {
        // No file => Select a file doc
        return Ok("# Select a file\n\nPress Enter to select a markdown file.\n".to_string());
    }
    let first = &files[0];
    if first == "-" {
        // Read stdin
        use std::io::Read;
        let mut buf = Vec::new();
        let stdin = std::io::stdin();
        let mut handle = stdin.lock();
        match handle.read_to_end(&mut buf) {
            Ok(0) => {
                // Empty (0 bytes) => error
                return Err(("Error reading input: Empty input provided\n".to_string(), 1));
            }
            Ok(_) => {
                if buf.is_empty() {
                    return Err(("Error reading input: Empty input provided\n".to_string(), 1));
                }
                match String::from_utf8(buf) {
                    Ok(s) => Ok(s),
                    Err(_) => Err(("Error reading input: I/O error: stream did not contain valid UTF-8\n".to_string(), 1)),
                }
            }
            Err(e) => {
                return Err((format!("Error reading input: I/O error: {}\n", e), 1));
            }
        }
    } else {
        // Check if directory?
        match std::fs::metadata(first) {
            Ok(md) if md.is_dir() => {
                return Ok("# Select a file\n\nPress Enter to select a markdown file.\n".to_string());
            }
            Ok(_) => {},
            Err(e) => {
                // Not found or other? If not found, error. What about permission? metadata fails with permission? For permission denied on file? Actually metadata on file with 000 still succeeds (since directory readable)? For /tmp/noperm.md with 000, metadata succeeds (since file exists), but read fails with permission denied. So here, only handle not found? But original for nonexistent gives I/O error. For permission denied on read, handle below.
                // If metadata fails, it's likely not found (or permission on parent?). Return I/O error.
                return Err((format!("Error reading input: I/O error: {}\n", e), 1));
            }
        }
        // Try to read file
        match std::fs::read_to_string(first) {
            Ok(s) => Ok(s),
            Err(e) => {
                // Check if error is InvalidData (UTF-8)? read_to_string gives InvalidData with "stream did not contain valid UTF-8". Good, format as I/O error.
                Err((format!("Error reading input: I/O error: {}\n", e), 1))
            }
        }
    }
}

fn print_list(doc: &crate::markdown::Document, level: Option<u64>, filter: Option<&str>) {
    let mut heads = &doc.headings;
    // Bug: if both level and filter, ignore filter
    let filtered: Vec<&crate::markdown::Heading> = if level.is_some() && filter.is_some() {
        let lvl = level.unwrap();
        heads.iter().filter(|h| h.level as u64 == lvl).collect()
    } else if let Some(lvl) = level {
        heads.iter().filter(|h| h.level as u64 == lvl).collect()
    } else if let Some(pat) = filter {
        let lower = pat.to_lowercase();
        heads.iter().filter(|h| h.text.to_lowercase().contains(&lower)).collect()
    } else {
        heads.iter().collect()
    };
    for h in filtered {
        // Format: "#"*level + " " + text + "\n" (even when text empty, keep space)
        print!("{} {}\n", "#".repeat(h.level as usize), h.text);
    }
}

fn print_tree(doc: &crate::markdown::Document) {
    // Build tree already in doc.sections, render with box-drawing
    // For empty (0 headings), print nothing (empty)
    if doc.sections.is_empty() {
        return;
    }
    render_sections(&doc.sections, "", true);
}

fn render_sections(sections: &[crate::markdown::Section], prefix: &str, is_root: bool) {
    for (idx, sec) in sections.iter().enumerate() {
        let is_last = idx + 1 == sections.len();
        let connector = if is_last { "└──" } else { "├──" };
        // Heading display: "#"*level + " " + text? Actually for tree, format is like "└──# Title" (no space after ──? It's "└──# Title" with "#" directly after ──, then space? Let's see: "└──# Title" (└,─,─,#,space,Title). For "├──## Installation" (├──,##,space,Installation). Good. So prefix + "#"*level + " " + text? For empty text headings ("#" alone, text ""), what does tree show? For "#" (level1, empty), list shows "# \n" (with space). Tree would show "└──# \n"? (with space after #?). Let's assume same: "#"*level + " " + text.
        // But need to check: for "# " (empty), tree output? Let's test later.
        let heading_str = format!("{} {}", "#".repeat(sec.heading.level as usize), sec.heading.text);
        // For root level, prefix is "" (no indent), line is connector + heading_str
        // For nested, prefix is parent indent (e.g., "   " for last parent, "│  " for non-last)
        // Our render_sections is called recursively with prefix for children.
        // For current level, line = prefix + connector + heading_str
        // Wait for root, prefix "" => line "└──# Title". Good.
        // For children of Title (which is last root, so children prefix "   "), first child Installation (not last): line "   ├──## Installation". Good. Our recursion should pass correct prefix.
        print!("{}{}{}\n", prefix, connector, heading_str);
        // Children prefix: current prefix + (if is_last { "   " } else { "│  " })
        let child_prefix = format!("{}{}", prefix, if is_last { "   " } else { "│  " });
        if !sec.children.is_empty() {
            render_sections(&sec.children, &child_prefix, false);
        }
    }
}

