fn print_count(doc: &crate::markdown::Document) {
    // Heading counts: only levels that exist, in order 1-6, format "  #: 1" etc.
    // Header "Heading counts:\n", then for each level with count>0: "  {}: {}\n" where {} is "#"*level, then "\nTotal: {}\n"
    // For 0 headings: "Heading counts:\n\nTotal: 0\n" (header, blank, total)
    println!("Heading counts:");
    let mut counts = [0usize; 7]; // 1..6
    for h in &doc.headings {
        if h.level>=1 && h.level<=6 {
            counts[h.level as usize]+=1;
        }
    }
    for lvl in 1..=6 {
        if counts[lvl]>0 {
            println!("  {}: {}", "#".repeat(lvl), counts[lvl]);
        }
    }
    println!();
    println!("Total: {}", doc.heading_count);
}

