fn build_list_json(doc: &crate::markdown::Document) -> serde_json::Value {
    use serde_json::json;
    let sections_json: Vec<serde_json::Value> = doc.sections.iter().map(|s| section_to_json(s)).collect();
    json!({
        "document": {
            "metadata": {
                "source": null,
                "headingCount": doc.heading_count,
                "maxDepth": doc.max_depth,
                "wordCount": doc.word_count
            },
