fn section_to_json(sec: &crate::markdown::Section) -> serde_json::Value {
    use serde_json::json;
    let blocks_json: Vec<serde_json::Value> = sec.blocks.iter().map(|b| block_to_json(b)).collect();
    let children_json: Vec<serde_json::Value> = sec.children.iter().map(|c| section_to_json(c)).collect();
    json!({
        "id": sec.heading.id,
        "level": sec.heading.level,
        "title": sec.heading.text,
        "slug": sec.heading.slug,
        "position": {"line": sec.heading.pos_line, "offset": sec.heading.offset},
        "content": {"raw": sec.raw, "blocks": blocks_json},
        "children": children_json
    })
}

fn block_to_json(block: &crate::markdown::Block) -> serde_json::Value {
    use serde_json::json;
    match block {
        crate::markdown::Block::Paragraph{content, inline} => {
            let inline_json: Vec<serde_json::Value> = inline.iter().map(|i| inline_to_json(i)).collect();
            json!({"type":"paragraph","content":content,"inline":inline_json})
        },
        crate::markdown::Block::Code{language, content} => {
            // For json, start_line/end_line are section_pos (passed during parse_blocks). Our Block::Code currently doesn't store start/end? We removed them (simplified to language+content). Need to add them back? Our Block::Code in simplified version has only language+content, no start/end. But json needs start_line/end_line. We passed section_pos during parse_blocks, but didn't store. Need to fix Block::Code to include start/end.
            // For now, use 2 as placeholder? Actually need section_pos. Let's store in Block::Code.
            // Temporary: use 2? Will fix.
            json!({"type":"code","language":language,"content":content,"start_line":2,"end_line":2})
        },
        crate::markdown::Block::Table{headers, alignments, rows} => {
            json!({"type":"table","headers":headers,"alignments":alignments,"rows":rows})
        },
        crate::markdown::Block::List{ordered, items} => {
            let items_json: Vec<serde_json::Value> = items.iter().map(|it| {
                let inline_json: Vec<serde_json::Value> = it.inline.iter().map(|i| inline_to_json(i)).collect();
                json!({"checked":it.checked,"content":it.content,"inline":inline_json})
            }).collect();
            json!({"type":"list","ordered":ordered,"items":items_json})
        },
        crate::markdown::Block::Blockquote{content, blocks} => {
            let inner: Vec<serde_json::Value> = blocks.iter().map(|b| block_to_json(b)).collect();
            json!({"type":"blockquote","content":content,"blocks":inner})
        },
        crate::markdown::Block::Heading{level, content, inline, anchor} => {
            let inline_json: Vec<serde_json::Value> = inline.iter().map(|i| inline_to_json(i)).collect();
            json!({"type":"heading","level":level,"content":content,"inline":inline_json,"anchor":anchor})
        },
        crate::markdown::Block::HorizontalRule => {
            json!({"type":"horizontalrule"})
        },
    }
}

fn inline_to_json(inline: &crate::markdown::Inline) -> serde_json::Value {
    use serde_json::json;
    match inline {
        crate::markdown::Inline::Text(v) => json!({"type":"text","value":v}),
        crate::markdown::Inline::Link{text, url, title} => json!({"type":"link","text":text,"url":url,"title":title}),
        crate::markdown::Inline::Image{alt, src, title} => json!({"type":"image","alt":alt,"src":src,"title":title}),
    }
}

