// Lexer
#[derive(Debug, Clone, PartialEq)]
enum Tok {
    Dot, Ident(String), LBracket, RBracket, LParen, RParen, Comma, Colon, Pipe, Gt, GtGt,
    Plus, Minus, Star, Slash, Percent, EqEq, NotEq, GtEq, LtEq, Lt,
    And, Or, Not, True, False, Null,
    Str(String), Num(f64),
    Eof,
}
struct Lexer<'a>{
    input: &'a str,
    chars: Vec<char>,
    pos: usize,
    // For error positions: need byte offset? Use char pos for caret (assuming ASCII? For unicode headings, need byte? But queries are ASCII mostly. Use char pos for column.
}
impl<'a> Lexer<'a>{
    fn new(input: &'a str)->Self{
        Self{input, chars: input.chars().collect(), pos:0}
    }
    fn peek(&self)->Option<char>{self.chars.get(self.pos).copied()}
    fn peek2(&self)->Option<char>{self.chars.get(self.pos+1).copied()}
    fn advance(&mut self)->Option<char>{
        let c=self.chars.get(self.pos).copied()?;
        self.pos+=1;
        Some(c)
    }
    fn skip_ws(&mut self){
        while let Some(c)=self.peek(){
            if c==' '||c=='\t'||c=='\n'||c=='\r'{self.pos+=1;}else{break;}
        }
    }
    fn lex(&mut self)->Result<Vec<(Tok,usize)>,String>{
        let mut toks=Vec::new();
        while {
            self.skip_ws();
            self.peek().is_some()
        }{
            let start=self.pos;
            let c=self.peek().unwrap();
            match c{
                '.'=>{
                    // Check for .. (error: Expected identifier, found '.'?) Actually ".." should lex as Dot,Dot, then parser errors. Good.
                    self.advance();
                    toks.push((Tok::Dot,start));
                },
                '['=>{self.advance();toks.push((Tok::LBracket,start));},
                ']'=>{self.advance();toks.push((Tok::RBracket,start));},
                '('=>{self.advance();toks.push((Tok::LParen,start));},
                ')'=>{self.advance();toks.push((Tok::RParen,start));},
                ','=>{self.advance();toks.push((Tok::Comma,start));},
                ':'=>{self.advance();toks.push((Tok::Colon,start));},
                '|'=>{
                    self.advance();
                    // Check for ||? Actually "||" is two pipes? For ".h || .h", second '|' is start of next pipe without left? Parser will error "Expected expression, found '|'". Good. So lex each '|' separately, don't combine.
                    toks.push((Tok::Pipe,start));
                },
                '>'=>{
                    self.advance();
                    if self.peek()==Some('>'){
                        self.advance();
                        toks.push((Tok::GtGt,start));
                    }else if self.peek()==Some('='){
                        self.advance();
                        toks.push((Tok::GtEq,start));
                    }else{
                        toks.push((Tok::Gt,start));
                    }
                },
                '<'=>{
                    self.advance();
                    if self.peek()==Some('='){
                        self.advance();
                        toks.push((Tok::LtEq,start));
                    }else{
                        toks.push((Tok::Lt,start));
                    }
                },
                '='=>{
                    self.advance();
                    if self.peek()==Some('='){
                        self.advance();
