    let caret_pos=4+pos;
    let spaces=" ".repeat(caret_pos);
    format!("error: {}\n  --> query\n  |\n1 | {}\n{}^  {}\n\n", msg, input, spaces, _kind)
}
fn format_parse_error_len(input: &str, pos: usize, len: usize, msg: &str, kind: &str)->String{
    let caret_pos=4+pos;
    let spaces=" ".repeat(caret_pos);
    let carets="^".repeat(len.max(1));
    format!("error: {}\n  --> query\n  |\n1 | {}\n{}{}  {}\n\n", msg, input, spaces, carets, kind)
}
fn format_invalid_filter(input: &str, bracket_pos: usize)->String{
    // Error: "error: Invalid filter: expected filter pattern or index\n  --> query\n  |\n1 | .h[\n       ^  invalid filter\n\n" with caret at '[' (bracket_pos).
    let caret_pos=4+bracket_pos;
    let spaces=" ".repeat(caret_pos);
    format!("error: Invalid filter: expected filter pattern or index\n  --> query\n  |\n1 | {}\n{}^  invalid filter\n\n", input, spaces)
}
