fn find_section<'a>(sections: &'a [crate::markdown::Section], h: &crate::markdown::Heading)->Option<&'a crate::markdown::Section>{
    for sec in sections{
        if sec.heading.line==h.line && sec.heading.level==h.level && sec.heading.text==h.text{
            return Some(sec);
        }
        if let Some(found)=find_section(&sec.children, h){
            return Some(found);
        }
    }
    None
}
fn find_section_with_children<'a>(sections: &'a [crate::markdown::Section], h: &crate::markdown::Heading)->Option<(&'a crate::markdown::Section, bool)>{
    // Returns (section, found) where section includes children (as stored). Actually find_section already returns section with children. Good. So just call find_section.
    find_section(sections, h).map(|s| (s, true))
