fn resolve_tui_input(files: &[String]) -> Result<(String, String, bool, Vec<String>), (String, i32)> {
    if files.is_empty() {
        let content = "# Select a file\n\nPress Enter to select a markdown file.\n".to_string();
        let picker = list_md_files(".");
        return Ok((content, "stdin".to_string(), true, picker));
    }
    if files.len() == 1 {
        let f = &files[0];
        if f == "-" {
            use std::io::Read;
            let mut buf = Vec::new();
            let stdin = std::io::stdin();
            let mut handle = stdin.lock();
            match handle.read_to_end(&mut buf) {
                Ok(0) => {
                    if buf.is_empty() {
                        return Err(("Error reading input: Empty input provided\n".to_string(), 1));
                    } else {
                        match String::from_utf8(buf) {
                            Ok(s) => return Ok((s, "stdin".to_string(), false, vec![])),
                            Err(_) => return Err(("Error reading input: I/O error: stream did not contain valid UTF-8\n".to_string(), 1)),
                        }
                    }
                },
                Ok(_) => {
                    if buf.is_empty() {
                        return Err(("Error reading input: Empty input provided\n".to_string(), 1));
                    }
                    match String::from_utf8(buf) {
                        Ok(s) => return Ok((s, "stdin".to_string(), false, vec![])),
                        Err(_) => return Err(("Error reading input: I/O error: stream did not contain valid UTF-8\n".to_string(), 1)),
                    }
                },
                Err(e) => {
                    if buf.is_empty() {
                        return Err(("Error reading input: Empty input provided\n".to_string(), 1));
                    } else {
                        return Err((format!("Error reading input: I/O error: {}\n", e), 1));
                    }
                }
            }
        } else {
            match std::fs::metadata(f) {
                Ok(md) if md.is_dir() => {
                    let content = "# Select a file\n\nPress Enter to select a markdown file.\n".to_string();
                    let picker = list_md_files(f);
                    return Ok((content, "stdin".to_string(), true, picker));
                },
                Ok(_) => {},
                Err(e) => {
                    return Err((format!("Error reading input: I/O error: {}\n", e), 1));
                }
            }
            match std::fs::read_to_string(f) {
                Ok(s) => {
                    let disp = std::path::Path::new(f).file_name().and_then(|n| n.to_str()).unwrap_or(f).to_string();
                    return Ok((s, disp, false, vec![]));
                },
                Err(e) => {
                    return Err((format!("Error reading input: I/O error: {}\n", e), 1));
                }
            }
        }
    } else {
        let content = "# Select a file\n\nPress Enter to select a markdown file.\n".to_string();
        return Ok((content, "stdin".to_string(), true, files.to_vec()));
    }
}

fn list_md_files(dir: &str) -> Vec<String> {
    let mut out = Vec::new();
    let path = std::path::Path::new(dir);
    if let Ok(entries) = std::fs::read_dir(path) {
        for entry in entries.flatten() {
            let p = entry.path();
            if p.is_file() {
                if let Some(ext) = p.extension().and_then(|e| e.to_str()) {
                    let lower = ext.to_lowercase();
                    if lower == "md" || lower == "markdown" {
                        if let Some(name) = p.file_name().and_then(|n| n.to_str()) {
                            out.push(name.to_string());
                        }
                    }
                }
            }
        }
    }
    out.sort();
    out
}

