fn get_section_content(doc: &crate::markdown::Document, idx: usize) -> (String, String) {
    if doc.headings.is_empty() {
        return ("(Document)".to_string(), String::new());
    }
    let h = &doc.headings[idx.min(doc.headings.len()-1)];
    let title = h.text.clone();
    let mut end = doc.lines.len();
    for k in idx+1..doc.headings.len() {
        let h2 = &doc.headings[k];
        if h2.is_setext { continue; }
        if h2.start_idx == usize::MAX { continue; }
        if h2.level <= h.level {
            end = h2.start_idx;
            break;
        }
    }
    let start = if h.start_idx == usize::MAX { 0 } else { h.start_idx + 1 };
    let slice = if start < end && end <= doc.lines.len() {
        &doc.lines[start..end]
    } else {
        &[][..]
    };
    let mut s = 0;
    let mut e = slice.len();
    while s < e && slice[s].trim().is_empty() { s += 1; }
    while e > s && slice[e-1].trim().is_empty() { e -= 1; }
    let content_text = slice[s..e].join("\n");
    (title, content_text)
}
