    let safe2 = !s.is_empty() && s.chars().all(|c| c.is_ascii_alphanumeric() || c == '_' || c == '-' || c == '.' || c == '/' || c == ':' || c == ',' || c == '@' || c == '%' || c == '+' || c == '=');
    if safe2 {
        Ok(Cow::Borrowed(s))
    } else if s.is_empty() {
        Ok(Cow::Borrowed("''"))
    } else {
        // Single-quote with escaping: replace ' with '\'' (close, escaped, open)
        let mut out = String::with_capacity(s.len() + 2);
        out.push('\'');
        for c in s.chars() {
            if c == '\'' {
                out.push_str("'\\''");
            } else {
                out.push(c);
            }
        }
        out.push('\'');
        Ok(Cow::Owned(out))
    }
}

pub fn quote(s: &str) -> Cow<'_, str> {
    try_quote(s).unwrap_or(Cow::Borrowed(s))
}
